function parseEdges(text){
  var nodes={}, edges=[];
  var lines=String(text||'').split(/\r?\n/);
  for(var i=0;i<lines.length;i++){
    var ln=lines[i].trim();
    if(!ln) continue;
    var m=ln.split(/\s*(?:->|=>)\s*/);
    if(m.length!==2 || !m[0] || !m[1]) return { nodes:null, edges:null, error:'第 '+(i+1)+' 行格式错误（需 a -> b）' };
    nodes[m[0]]=1; nodes[m[1]]=1;
    edges.push([m[0], m[1]]);
  }
  return { nodes:Object.keys(nodes), edges:edges, error:null };
}
function topoSort(nodes, edges){
  var indeg={}, adj={};
  nodes.forEach(function(n){ indeg[n]=0; adj[n]=[]; });
  edges.forEach(function(e){
    if(!(e[0] in indeg) || !(e[1] in indeg)) throw new Error('UNKNOWN_NODE');
    adj[e[0]].push(e[1]); indeg[e[1]]++;
  });
  var q=nodes.filter(function(n){ return indeg[n]===0; }).sort();
  var order=[];
  while(q.length){
    var n=q.shift(); order.push(n);
    adj[n].sort().forEach(function(m){ indeg[m]--; if(indeg[m]===0){ q.push(m); q.sort(); } });
  }
  if(order.length!==nodes.length){
    var cyc=nodes.filter(function(n){ return order.indexOf(n)<0; });
    return { order:null, cycle:cyc };
  }
  return { order:order, cycle:null };
}
function levels(nodes, edges){
  var indeg={}, adj={};
  nodes.forEach(function(n){ indeg[n]=0; adj[n]=[]; });
  edges.forEach(function(e){ adj[e[0]].push(e[1]); indeg[e[1]]++; });
  var out=[], cur=nodes.filter(function(n){ return indeg[n]===0; }).sort();
  var seen=0;
  while(cur.length){
    out.push(cur);
    seen+=cur.length;
    var next={};
    cur.forEach(function(n){ adj[n].forEach(function(m){ indeg[m]--; if(indeg[m]===0) next[m]=1; }); });
    cur=Object.keys(next).sort();
  }
  if(seen!==nodes.length) return null;
  return out;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parseEdges:parseEdges, topoSort:topoSort, levels:levels };
}
if (typeof window !== 'undefined') {
  window.TopoForgePure = { parseEdges:parseEdges, topoSort:topoSort, levels:levels };
}
